import{_ as o,l as s,o as a,c,v as r,p as l,x as t,d,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"writeback","description":"","frontmatter":{"title":"writeback","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/writeback.md","filePath":"cs/writeback.md","lastUpdated":1789023840000}'),p={name:"cs/writeback.md"};function f(m,e,u,_,b,E){const i=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="writeback" tabindex="-1">writeback <a class="header-anchor" href="#writeback" aria-label="Permalink to &quot;writeback&quot;">​</a></h1><div class="epigraph"><p>脏页不在每次 write 时落盘；后台按比例与老化把它们排成回写，平衡吞吐与崩溃窗口。</p><footer>—— 据 Silberschatz 对延迟写的讨论；Love 对 Linux 写回的整理</footer></div><p><a href="/cs/page-cache">上一课</a>把脏位置在页上。<a href="/cs/buffer-dirty">缓冲与脏页</a> 说回写可由定时器、压力或 fsync 触发。缺口是<strong>策略引擎</strong>：脏比例、过期时间、flusher 线程、以及与 <a href="/cs/memory-reclaim">内存回收</a> 抢同一套 LRU 时谁先写。不是磁盘电梯——那是更后的块层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写回太勤，随机小写变成同步盘；太懒，崩溃窗口大，且回收时才发现全是脏页、分配卡死。缺口：维护脏页数量与阈值（如脏占内存比例）；超过后台阈值则 flusher 写；超过限制阈值则写者自己同步写（dirty throttling）。按 inode 或按 bdi（backing device）排队，避免一个文件饿死其他设备。</p><p>本课不把每版 <code>dirty_ratio</code> 的默认整数当考纲。</p><p><span class="marginnote">老化：页脏了多久。老脏页优先，减少「永远不刷的冷脏页」。laptop 模式可把回写攒成突发以让盘休眠。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>write</code> 只改页 Cache 并记账。kupdate/flusher：选过期或超额的 inode，调用 <a href="/cs/vfs">VFS</a> 的 <code>writepages</code>。回收路径上若碰到脏文件页，先加入回写再等完成或换一个牺牲。与 swap 写回并列但目标不同：这里写文件，不是槽。完成中断后清脏位。</p>',9)),(a(),l(h,null,{default:t(()=>[n(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WRITE%5B%22write%20%E6%A0%87%E8%84%8F%22%5D%20--%3E%20RATIO%5B%22%E8%84%8F%E6%AF%94%E4%BE%8B%22%5D%0A%20%20RATIO%20--%3E%20BG%5B%22%E5%90%8E%E5%8F%B0%20flusher%22%5D%0A%20%20RATIO%20--%3E%20THR%5B%22%E8%BF%87%E9%99%90%E5%88%99%E5%86%99%E8%80%85%E8%8A%82%E6%B5%81%22%5D%0A%20%20BG%20--%3E%20DEV%5B%22writepages%20%E5%88%B0%E5%9D%97%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>writeback 把延迟写收成可调的控制环，让 <a href="/cs/scheduling-metrics">调度</a> 看到的 I/O 等待成批出现而不是每次 <code>write</code>。它不提供 <code>write</code> 返回即持久——那是下一课 fsync。崩溃时未刷的脏页丢失，正是窗口的含义。不要把组提交的数据库日志提前写进本课；文件系统日志在更后。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cgroup 写回带宽限制的全文。不保证 SSD 上「老化」仍有机械盘那种意义，但节流仍防写爆。下一课用户要一条系统调用等待「与此文件相关的脏页到达稳定介质」。</p><p>后课默认：回写是尽力的、异步的。显式持久是 fsync。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>flusher 按脏比例与老化写回页 Cache。</li><li>过限则写者阻塞，避免内存被脏页填满。</li><li>单文件持久等待是 fsync 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const T=o(p,[["render",f]]);export{w as __pageData,T as default};
